function modelToDelegate(modelName) {
  return modelName.charAt(0).toLowerCase() + modelName.slice(1);
}

function decodeSpecialValue(type, value) {
  if (value === null || value === undefined) return value;

  if (type === "DateTime") return new Date(value);
  if (type === "BigInt") return BigInt(value);
  if (type === "Bytes") return Buffer.from(value, "base64");

  return value;
}

function reviveRow(modelName, row) {
  const types = FIELD_TYPES[modelName] || {};
  const out = {};

  for (const [key, value] of Object.entries(row)) {
    const type = types[key];
    out[key] = type ? decodeSpecialValue(type, value) : value;
  }

  return out;
}

async function clearData() {
  for (const modelName of DELETE_ORDER) {
    const delegate = modelToDelegate(modelName);
    if (!prisma[delegate]) {
      throw new Error(`Delegate not found for model ${modelName} (${delegate})`);
    }
    await prisma[delegate].deleteMany();
  }
}

async function insertData() {
  for (const modelName of INSERT_ORDER) {
    const delegate = modelToDelegate(modelName);
    if (!prisma[delegate]) {
      throw new Error(`Delegate not found for model ${modelName} (${delegate})`);
    }

    const rows = (SEED_DATA[modelName] || []).map((row) => reviveRow(modelName, row));

    if (!rows.length) {
      console.log(`- ${modelName}: 0 rows`);
      continue;
    }

    for (let i = 0; i < rows.length; i += BATCH_SIZE) {
      const batch = rows.slice(i, i + BATCH_SIZE);
      await prisma[delegate].createMany({ data: batch });
    }

    console.log(`- ${modelName}: inserted ${rows.length} rows`);
  }
}

async function main() {
  console.log("🌱 Running snapshot seed...");
  await clearData();
  await insertData();
  console.log("✅ Snapshot seed completed.");
}

main()
  .catch((error) => {
    console.error("❌ Snapshot seed failed", error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
